"""The confirmatory search analysis end to end on synthetic snack data generated by the search model itself.

When choices, search and response times come from sample until return, the analysis must find the model's
sensitivity, a search elasticity near the one it predicts, a time law that favors its effort over the static
models' effort, and a positive rank correlation between expected looks and response time. No real data are used.
"""

from __future__ import annotations

import numpy as np
import pytest

from overload import snack
from overload.experiments import search_confirmatory as sc

LAM = 0.7
PARTICIPANTS = 12


def _simulate(rng: np.random.Generator, trials: int = 160) -> snack.SnackData:
    blocks = []
    for n in snack.SET_SIZES:
        values = rng.integers(-3, 4, size=(trials, n)).astype(float)
        seen = np.zeros((trials, n), dtype=bool)
        choice = np.zeros(trials, dtype=int)
        looks = np.zeros(trials)
        for t in range(trials):
            q = np.exp(LAM * values[t])
            q /= q.sum()
            visited, k = set(), 0
            while True:
                i = int(rng.choice(n, p=q))
                k += 1
                if i in visited:
                    choice[t] = i
                    break
                visited.add(i)
                seen[t, i] = True
            looks[t] = k
        rt = 1000.0 * (1.0 + 0.4 * looks) * np.exp(rng.normal(0.0, 0.15, size=trials))
        participant = rng.integers(0, PARTICIPANTS, size=trials)
        blocks.append(snack.Block(n, values, choice, seen, participant, rt))
    return snack.SnackData(tuple(blocks), tuple(range(PARTICIPANTS)))


@pytest.fixture(scope="module")
def point():
    data = _simulate(np.random.default_rng(21))
    sc._STATE.update(data=data, prep=sc.prepare(data))
    return sc.run_replicate(-1)


def test_the_search_sensitivity_is_recovered(point):
    assert np.allclose(point["lambda"]["SR"], LAM, atol=0.15)


def test_search_elasticity_matches_the_model(point):
    s1 = point["S1"]
    assert s1["observed_elasticity"] < 1.0
    assert s1["predicted_elasticity"] == pytest.approx(s1["observed_elasticity"], abs=0.1)
    assert np.allclose(s1["predicted"], s1["observed"], rtol=0.1)


def test_time_law_prefers_the_search_effort(point):
    err = {m: point["S2"][m]["error"] for m in sc.MODELS}
    assert err["SR"] < err["CL"] and err["SR"] < err["DbS_avg"]


def test_expected_looks_foresee_slow_trials(point):
    # the forecast carries only the part of search length that the display decides, the rest is chance, so the
    # correlation is modest even when the model is true
    assert point["S3"]["looks_SR"] > 0.03


def test_scores_are_finite(point):
    for m in sc.MODELS:
        assert np.isfinite(point["L"][m]["L"])
        assert np.isfinite(point["S4"][m]["score"])
    assert np.isfinite(point["implied_elasticity"])


@pytest.mark.parametrize(
    "percentile, basic, noninferior, better",
    [
        ([-1.5, 3.0], [-1.0, 3.5], True, False),
        ([-2.5, 3.0], [-1.0, 3.5], False, False),
        ([-1.0, 3.0], [-2.1, 3.5], False, False),
        ([0.4, 3.0], [0.1, 3.5], True, True),
        ([0.4, 3.0], [-0.1, 3.5], True, False),
    ],
)
def test_noninferiority_rule(percentile, basic, noninferior, better):
    d = sc.noninferiority({"percentile": percentile, "basic": basic}, margin=2.0)
    assert (d["noninferior"], d["better"]) == (noninferior, better)


def test_a_bootstrap_replicate_runs_and_differs():
    data = _simulate(np.random.default_rng(22), trials=80)
    sc._STATE.update(data=data, prep=sc.prepare(data))
    a, b = sc.run_replicate(-1), sc.run_replicate(0)
    assert a["S1"]["observed"] != b["S1"]["observed"]
    summary = sc.summarize_all(a, [b, sc.run_replicate(1)])
    assert set(summary) >= {"S1", "S2", "S3", "S4", "S5", "choices"}
    assert summary["S5"]["margin"] == sc.NONINFERIORITY


@pytest.mark.parametrize("t0, tau", [(2.0, 0.3), (0.0, 0.05), (3.0, 0.0), (0.5, 5.0)])
def test_time_law_finds_the_global_minimum(t0, tau):
    rng = np.random.default_rng(3)
    e = np.repeat([9.0, 16.0, 25.0, 36.0], 200) * rng.uniform(0.5, 1.5, 800)
    y = np.log(t0 + tau * e + 1e-12) + rng.normal(0.0, 0.2, e.size)
    w = rng.integers(0, 3, e.size).astype(float)
    a, b = sc.fit_time_law(e, y, w)

    def sse(t, u):
        return float(w @ (y - np.log(t + u * e)) ** 2)

    best = sse(a, b)
    T = np.concatenate([[sc.T0_MIN], np.geomspace(1e-6, 1e3, 241)])
    U = np.concatenate([[0.0], np.geomspace(1e-6, 1e2, 241)])
    brute = min(sse(t, u) for t in T for u in U if t + u > 0)
    assert a >= sc.T0_MIN and b >= 0.0
    assert best <= brute + 1e-9
